import React from 'react';
import member from '../../../assets/member.png';
import President from '../../../assets/president.png';

const roles = [
  { title: 'President', name: 'Mr. XYZ Patel', img: President },
  { title: 'Vice-President', name: 'Mr. XYZ Patel', img: President },
  { title: 'Secretary', name: 'Mr. XYZ Patel', img: President },
  { title: 'Treasurer', name: 'Mr. XYZ Patel', img: member },
];

const members = Array(8).fill({
  title: 'Member',
  name: 'Mr. XYZabc Patel',
  img: member,
});

export default function CommitteeTreeSVG() {
  return (
    <section className="py-10 px-4 max-w-7xl mx-auto">
      <h2 className="text-2xl font-bold mb-12 text-center">Our Committee</h2>

      <div className="relative flex flex-col items-center">
        {/* President */}
        <NodeCard {...roles[0]} className="mb-16" id="president" />

        {/* SVG Connector: President to VP/Secretary/Treasurer */}
        <ConnectorSVG />

        {/* 2nd level: VP, Secretary, Treasurer */}
        <div
          id="second-level"
          className="flex justify-center space-x-20 mb-14 relative"
          style={{ minWidth: 480 }}
        >
          {roles.slice(1).map((role, i) => (
            <NodeCard key={i} {...role} id={`role-${i + 1}`} />
          ))}
        </div>

        {/* Members Grid */}
        <div
          className="grid grid-cols-2 md:grid-cols-4 gap-12 max-w-5xl"
          style={{ marginTop: '3rem' }}
        >
          {members.map((member, i) => (
            <NodeCard key={i} {...member} />
          ))}
        </div>
      </div>
    </section>
  );
}

function NodeCard({ img, title, name, className, id }) {
  return (
    <div
      id={id}
      className={`text-center p-4 border rounded shadow w-36 mx-auto bg-white relative ${className || ''}`}
      style={{ minWidth: '140px' }}
    >
      <img src={img} alt={title} className="w-20 h-20 mx-auto rounded-full mb-3 object-cover" />
      <div className="font-semibold text-md">{title}</div>
      <div className="text-xs text-gray-600">{name}</div>
    </div>
  );
}

function ConnectorSVG() {
  /*
   SVG will draw three curved paths connecting:
   - President (top center)
   - To each of VP, Secretary, Treasurer below

   We'll position SVG absolutely over the container and
   use relative coords matching the layout.
  */

  // Sizes should correspond to card widths + spacing

  return (
    <svg
      className="absolute top-[110px] left-0 w-full h-40 pointer-events-none"
      style={{ overflow: 'visible', zIndex: 0 }}
    >
      {/* Line from president to VP */}
      <path
        d="M50 0 C 75 40, 125 40, 150 80"
        stroke="#F48F0F"
        strokeWidth="3"
        fill="transparent"
      />
      {/* Line from president to Secretary */}
      <path
        d="M150 0 C 175 40, 225 40, 250 80"
        stroke="#F48F0F"
        strokeWidth="3"
        fill="transparent"
      />
      {/* Line from president to Treasurer */}
      <path
        d="M250 0 C 275 40, 325 40, 350 80"
        stroke="#F48F0F"
        strokeWidth="3"
        fill="transparent"
      />
    </svg>
  );
}
